1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Set;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.model.OwnerRegion;
10	
11	/**
12	 * Single source of truth for an owner's {@code customerCode} and everything read back out of it.
13	 *
14	 * <p>The code is formatted {@code <REGION>-<HASH8>}:
15	 * <ul>
16	 * <li>{@code REGION} is the owner's region code, derived from the postcode (see
17	 * {@link OwnerRegion#localityOf}, which prefers the postcode and falls back to the city table), e.g.
18	 * {@code NSW}.</li>
19	 * <li>{@code HASH8} is the first eight upper-case hex characters of the SHA-256 of
20	 * {@code normalizedTelephone + lastName}, where {@code normalizedTelephone} is the E.164 telephone
21	 * (see {@link OwnerTelephone#toE164}).</li>
22	 * </ul>
23	 *
24	 * <p>There are no sequence numbers: the code depends only on the owner's own region, telephone and
25	 * last name, so it can be computed without coordinating through the database. Every other identity
26	 * value is derived from this code — the membership number and its Luhn check digit, the create audit
27	 * record and the read-time {@code locality} all read the region-and-hash code assigned here.
28	 */
29	public final class OwnerCustomerCode {
30	
31	    private OwnerCustomerCode() {
32	    }
33	
34	    /** The {@code <REGION>-<HASH8>} customer code for {@code owner}. */
35	    public static String customerCode(Owner owner) {
36	        String region = OwnerRegion.localityOf(owner.getCity(), owner.getPostcode());
37	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
38	    }
39	
40	    /**
41	     * The {@code HASH8} segment: the first eight upper-case hex characters of the SHA-256 of the
42	     * normalized (E.164) telephone concatenated with the last name.
43	     */
44	    static String hash8(String telephone, String lastName) {
45	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
46	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
47	                + (lastName == null ? "" : lastName);
48	        try {
49	            byte[] digest = MessageDigest.getInstance("SHA-256")
50	                    .digest(key.getBytes(StandardCharsets.UTF_8));
51	            StringBuilder sb = new StringBuilder(8);
52	            for (int i = 0; i < 4; i++) {
53	                sb.append(String.format("%02X", digest[i]));
54	            }
55	            return sb.toString();
56	        }
57	        catch (NoSuchAlgorithmException ex) {
58	            throw new IllegalStateException("SHA-256 not available", ex);
59	        }
60	    }
61	
62	    /**
63	     * De-duplicates {@code base} against the {@code existing} customer codes: returns {@code base}
64	     * unchanged when it is not already taken, otherwise appends {@code -<n>} with the smallest
65	     * {@code n} of 2 or more that makes the code unique.
66	     */
67	    public static String deduplicate(String base, Set<String> existing) {
68	        if (!existing.contains(base)) {
69	            return base;
70	        }
71	        for (int n = 2; ; n++) {
72	            String candidate = base + "-" + n;
73	            if (!existing.contains(candidate)) {
74	                return candidate;
75	            }
76	        }
77	    }
78	
79	    /**
80	     * The {@code REGION} segment of a customer code (everything before the first {@code '-'}), or
81	     * {@code null} when there is no code to read it from.
82	     */
83	    public static String region(String customerCode) {
84	        if (customerCode == null) {
85	            return null;
86	        }
87	        int separator = customerCode.indexOf('-');
88	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
89	    }
90	}
