1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}, where {@code REGION}
12	 * is the region code derived from the postcode and {@code HASH8} is the first eight upper-case hex
13	 * characters of the SHA-256 of the normalized telephone concatenated with the last name (e.g.
14	 * {@code NSW-1A2B3C4D}). The shape and all of its parts are owned by {@link OwnerCustomerCode}.
15	 *
16	 * <p>The region-and-hash code depends only on the owner's own fields, but two distinct owners can
17	 * nonetheless hash to the same code. On a collision with an existing owner's {@code customerCode} the
18	 * code is de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes
19	 * it unique (see {@link OwnerCustomerCode#deduplicate}), so distinct owners always keep distinct
20	 * customer codes.
21	 */
22	public class AssignOwnerCustomerCode {
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        String base = OwnerCustomerCode.customerCode(owner);
26	        Set<String> existing = new HashSet<>();
27	        for (Owner other : ownerRepository.findAll()) {
28	            if (other.getCustomerCode() != null) {
29	                existing.add(other.getCustomerCode());
30	            }
31	        }
32	        owner.setCustomerCode(OwnerCustomerCode.deduplicate(base, existing));
33	    }
34	}
