1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Single source of truth for an owner's fiscal year — the financial year that starts on 1 July.
9	 *
10	 * <p>The fiscal year is named for the calendar year in which it <em>ends</em>: the year running
11	 * 1 July 2025 to 30 June 2026 is fiscal year 2026. Its label is {@code FY<YY>}, where {@code YY}
12	 * is the last two digits of that ending year (e.g. a date in October 2026 falls in fiscal year
13	 * 2027 and so has label {@code FY27}).
14	 *
15	 * <p>Every date-derived value that moved to a fiscal-year basis — the {@code fiscalYear} read
16	 * field, the membership number's year segment, and tenure — resolves through this class so they
17	 * cannot drift apart. All derive from the already-stored, business-day-adjusted
18	 * {@code registrationDate}.
19	 */
20	public final class OwnerFiscalYear {
21	
22	    private OwnerFiscalYear() {
23	    }
24	
25	    /**
26	     * The fiscal year a date falls in, named by its ending calendar year: the date's own year when
27	     * it is on or after 1 July, otherwise the previous year rolled forward — i.e. the date's year
28	     * plus one from July onwards.
29	     */
30	    public static int fiscalYear(LocalDate date) {
31	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
32	    }
33	
34	    /**
35	     * The {@code FY<YY>} label for an owner's business-day-adjusted {@code registrationDate}, or
36	     * {@code null} when no registration date is recorded.
37	     */
38	    public static String label(Owner owner) {
39	        LocalDate registrationDate = owner.getRegistrationDate();
40	        return registrationDate == null ? null : label(registrationDate);
41	    }
42	
43	    /** The {@code FY<YY>} label for a date (e.g. {@code FY27} for October 2026). */
44	    public static String label(LocalDate date) {
45	        return String.format("FY%02d", fiscalYear(date) % 100);
46	    }
47	
48	    /**
49	     * The number of whole fiscal years elapsed between two dates — the difference of their fiscal
50	     * years, never negative. Each crossing of a 1 July boundary counts as one elapsed fiscal year.
51	     */
52	    public static long elapsedFiscalYears(LocalDate from, LocalDate to) {
53	        return Math.max(fiscalYear(to) - fiscalYear(from), 0);
54	    }
55	}
