7	 * uniquely names the owner to the outside world.
8	 *
9	 * <p>Today that is the {@code customerCode}. When the {@code customerCode} is later unified into
10	 * the {@code memberId}, only this method changes to return the {@code memberId}; every consumer
11	 * (such as the {@code OWNER_CREATED} audit event emitted by {@link AuditOwnerCreated}) then carries
12	 * the new identifier without being touched.
13	 */
14	public final class OwnerPrimaryIdentifier {
15	
16	    private OwnerPrimaryIdentifier() {
17	    }
18	
19	    /** The owner's current primary identifier. */
