1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.OwnerRegion;
4	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
5	
6	/**
7	 * Single source of truth for an owner's derived {@code ownerSegment} — the marketing segment
8	 * formatted {@code <TIER>_<AREA>}: one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
9	 * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
10	 *
11	 * <p>TIER is {@code PREMIUM} when {@code membershipLevel} is 3 or more, otherwise {@code STANDARD}.
12	 * AREA is {@code METRO} when the owner's locality is a known region (NSW, VIC or QLD), otherwise
13	 * {@code REGIONAL}.
14	 *
15	 * <p>Derived at read time by the owner mapper from the already-stored membership level and the
16	 * owner's derived locality, so it needs no column of its own and can never drift.
17	 */
18	public final class OwnerSegment {
19	
20	    private OwnerSegment() {
21	    }
22	
23	    /**
24	     * The owner segment for the given {@code membershipLevel} and {@code locality}. A null
25	     * membership level is treated as below 3 (STANDARD); any locality that is not a known region
26	     * (per {@link OwnerRegion#isKnownRegion}) is REGIONAL.
27	     */
28	    public static OwnerDto.OwnerSegmentEnum segment(Integer membershipLevel, String locality) {
29	        boolean premium = membershipLevel != null && membershipLevel >= 3;
30	        boolean metro = OwnerRegion.isKnownRegion(locality);
31	        String tier = premium ? "PREMIUM" : "STANDARD";
32	        String area = metro ? "METRO" : "REGIONAL";
33	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
34	    }
35	}
