3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Single source of truth for an owner's {@code identityKey} — the value that both the owner mapper
11	 * returns and the create pipeline's duplicate detection compares on. The key is the lower-case hex
12	 * SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the
13	 * telephone is reduced to E.164 through {@link OwnerTelephone#toE164}, the email is lower-cased
14	 * through {@link OwnerEmail#normalize}, and the last name is reduced to its phonetic code through
15	 * {@link OwnerSoundex#soundex}. A missing telephone or email contributes an empty segment.
16	 *
17	 * <p>Because the telephone is part of the key, two owners who share a last name and postcode but
18	 * carry different telephones have <em>different</em> identity keys: they are not a hard duplicate.
19	 * That weaker, phonetic-name-plus-postcode overlap is handled as a soft match by
20	 * {@link FlagOwnerPossibleDuplicate}.
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /**
28	     * Builds the identity key from its three raw parts: the submitted/stored telephone (normalized
29	     * to E.164 here), the email (lower-cased here) and the last name (reduced to its Soundex code
30	     * here). The three normalized parts are joined with {@code '|'} and hashed with SHA-256; a
31	     * telephone or email that is {@code null} or cannot normalize contributes an empty segment.
32	     */
33	    public static String identityKey(String telephone, String email, String lastName) {
34	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
35	        String normalizedEmail = OwnerEmail.normalize(email);
36	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone) + "|"
37	                + (normalizedEmail == null ? "" : normalizedEmail) + "|"
38	                + OwnerSoundex.soundex(lastName);
39	        return sha256Hex(raw);
40	    }
41	
42	    /**
43	     * The identity key of an already-stored owner, read from its persisted fields. The single
44	     * {@code Owner}-to-key definition used by the owner mapper and by duplicate detection.
45	     */
46	    public static String identityKey(Owner owner) {
47	        return identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
48	    }
49	
50	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
51	    private static String sha256Hex(String value) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest(value.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder(digest.length * 2);
56	            for (byte b : digest) {
57	                sb.append(String.format("%02x", b));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException ex) {
62	            throw new IllegalStateException("SHA-256 not available", ex);
63	        }
64	    }
65	}
