1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Single source of truth for the fixed city-to-region table and the per-region postcode ranges.
7	 *
8	 * <p>This is a domain concept shared by the read-time {@code locality} derivation (see
9	 * {@code org.springframework.samples.petclinic.mapper.OwnerMapper}) and the create/update postcode
10	 * validation in the REST pipeline, so it lives in the business layer that both already depend on
11	 * rather than in either. A city not in the table has region {@link #UNKNOWN} and accepts any 4-digit
12	 * postcode.
13	 */
14	public final class OwnerRegion {
15	
16	    /** Region reported for a city that is not in the fixed table. */
17	    public static final String UNKNOWN = "UNKNOWN";
18	
19	    /** Fixed city-to-region table; any other city has region {@link #UNKNOWN}. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region to inclusive 4-digit postcode range {@code {low, high}}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Fixed region-to-timezone table, as IANA names; any other region has no timezone. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    private OwnerRegion() {
36	    }
37	
38	    /** The canonical region for {@code city}, or {@link #UNKNOWN} when the city is not in the table. */
39	    public static String regionOf(String city) {
40	        return CITY_REGION.getOrDefault(city, UNKNOWN);
41	    }
42	
43	    /**
44	     * Whether {@code region} is one of the fixed known regions (NSW, VIC, QLD) rather than
45	     * {@link #UNKNOWN} or any other value. Backed by the same canonical tables as the rest of
46	     * this class, so callers never need to re-list the region vocabulary.
47	     */
48	    public static boolean isKnownRegion(String region) {
49	        return REGION_POSTCODES.containsKey(region);
50	    }
51	
52	    /**
53	     * The IANA timezone name for {@code region} from the fixed region-to-timezone table
54	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane), or
55	     * {@code null} when the region (e.g. {@link #UNKNOWN}) has no mapping.
56	     */
57	    public static String timezoneOf(String region) {
58	        return REGION_TIMEZONE.get(region);
59	    }
60	
61	    /**
62	     * The locality for an owner, preferring the postcode: when {@code postcode} is a 4-digit value
63	     * inside a known region's range that region wins, disambiguating cities that share a name.
64	     * Otherwise (postcode absent, malformed, or in no known range) this falls back to the
65	     * city-to-region table, which still returns {@link #UNKNOWN} for an unknown city.
66	     */
67	    public static String localityOf(String city, String postcode) {
68	        String byPostcode = regionForPostcode(postcode);
69	        return byPostcode != null ? byPostcode : regionOf(city);
70	    }
71	
72	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
73	    private static String regionForPostcode(String postcode) {
74	        if (postcode == null || !postcode.matches("\\d{4}")) {
75	            return null;
76	        }
77	        int value = Integer.parseInt(postcode);
78	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
79	            int[] range = entry.getValue();
80	            if (value >= range[0] && value <= range[1]) {
81	                return entry.getKey();
82	            }
83	        }
84	        return null;
85	    }
86	
87	    /**
88	     * Whether {@code postcode} is acceptable for {@code city}. A postcode must be exactly four
89	     * digits; a city whose region is known must additionally fall within that region's inclusive
90	     * range, while a city with no known region accepts any 4-digit postcode.
91	     */
92	    public static boolean isPostcodeValid(String city, String postcode) {
93	        if (postcode == null || !postcode.matches("\\d{4}")) {
94	            return false;
95	        }
96	        int[] range = REGION_POSTCODES.get(regionOf(city));
97	        if (range == null) {
98	            return true;
99	        }
100	        int value = Integer.parseInt(postcode);
101	        return value >= range[0] && value <= range[1];
102	    }
103	}
104

