13	/**
14	 * Emits audit records on the dedicated {@code AUDIT} logger once a new owner has been persisted.
15	 *
16	 * <p>Two records are emitted:
17	 * <ul>
18	 * <li>a human-readable audit line carrying the owner id, the {@code customerCode}, the
19	 * {@code registrationDate}, the {@code membershipLevel} and the {@code membershipNumber}; and</li>
20	 * <li>an immutable structured JSON event
21	 * {@code {seq, ownerId, customerCode, membershipLevel, event:"OWNER_CREATED"}}, where {@code seq}
22	 * is a monotonically increasing integer across every create in this process.</li>
23	 * </ul>
24	 *
25	 * <p>The event's identifier is read through {@link OwnerPrimaryIdentifier}, so it always carries the
26	 * owner's current primary identifier &mdash; the {@code customerCode} today, and whatever replaces
27	 * it later (the {@code memberId}).
28	 */
29	public class AuditOwnerCreated {
30	
31	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
32	
33	    private static final JsonMapper JSON = JsonMapper.shared();
34	
35	    /** Monotonically increasing sequence across every owner created in this process. */
36	    private static final AtomicLong SEQ = new AtomicLong();
37	
38	    public void service(@Val Owner owner) {
39	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
40	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
41	                owner.getMembershipLevel(), owner.getMembershipNumber());
42	
43	        ObjectNode event = JSON.createObjectNode();
44	        event.put("seq", SEQ.incrementAndGet());
45	        event.put("ownerId", owner.getId());
46	        event.put("customerCode", OwnerPrimaryIdentifier.of(owner));
47	        event.put("membershipLevel", owner.getMembershipLevel());
48	        event.put("event", "OWNER_CREATED");
49	        AUDIT.info(JSON.writeValueAsString(event));
50	    }
51	}
