2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner-telephone E.164 rule. Both {@link ValidateOwnerFields}
8	 * (which normalizes the submitted value) and {@link OwnerIdentity} (which builds the identity key
9	 * compared against stored owners) convert through {@link #toE164} so the two can never drift apart.
10	 *
11	 * <p>The rule: strip spaces, dashes and brackets. If what remains starts with a '+', keep that
12	 * leading '+' and country code as-is. Otherwise assume Australian country code '+61', dropping a
13	 * single leading '0' from the national digits before prefixing. The result must be a '+' followed
14	 * by 8 to 15 digits; anything else cannot form valid E.164 and yields {@code null}.
15	 *
16	 * <p>The national-number length is then checked against the country calling code: '+61' requires
17	 * exactly 9 national digits and '+1' requires exactly 10. A number with the wrong national length
18	 * for its country code yields {@code null} (rejected as an invalid telephone). Country codes other
19	 * than these keep only the generic 8-to-15-digit bound.
20	 *
21	 * <p>Example: {@code "0412 345 678"} becomes {@code "+61412345678"}.
22	 */
23	public final class OwnerTelephone {
24	
25	    /**
26	     * Country calling code to required national-number length. Iteration order is longest code
27	     * first so a longer code is matched before a shorter one that is a prefix of it.
28	     */
29	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
30	
31	    static {
32	        NATIONAL_LENGTH.put("61", 9);
33	        NATIONAL_LENGTH.put("1", 10);
34	    }
35	
36	    private OwnerTelephone() {
37	    }
38	
39	    /**
40	     * Converts a submitted telephone to its E.164 form, or returns {@code null} when the value
41	     * cannot form a valid E.164 number.
42	     */
43	    static String toE164(String value) {
44	        if (value == null) {
45	            return null;
46	        }
47	        // Strip spaces, dashes and brackets; everything else must be a '+' or a digit.
48	        String cleaned = value.replaceAll("[\\s()\\-]", "");
49	        String digits;
50	        if (cleaned.startsWith("+")) {
51	            // Already international: keep the '+' and country code.
52	            digits = cleaned.substring(1);
53	        }
54	        else {
55	            // Assume '+61', dropping a single leading '0' from the national digits.
56	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
57	            digits = "61" + national;
58	        }
59	        // Require 8 to 15 digits (and nothing but digits) after the '+'.
60	        if (!digits.matches("[0-9]{8,15}")) {
61	            return null;
62	        }
63	        // Check the national-number length against the country calling code.
64	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH.entrySet()) {
65	            String code = entry.getKey();
66	            if (digits.startsWith(code)) {
67	                int nationalLength = digits.length() - code.length();
68	                return nationalLength == entry.getValue() ? "+" + digits : null;
69	            }
70	        }
71	        return "+" + digits;
72	    }
73	
74	    /**
75	     * Formats a stored E.164 telephone for humans as the country calling code, a space, then the
76	     * national digits grouped in threes from the left (e.g. {@code "+61412345678"} becomes
77	     * {@code "+61 412 345 678"}). The country calling code is identified from the known codes in
78	     * {@link #NATIONAL_LENGTH}; an unrecognized or non-E.164 value is returned unchanged.
79	     */
80	    public static String toDisplay(String e164) {
81	        if (e164 == null || !e164.startsWith("+")) {
82	            return e164;
83	        }
84	        String digits = e164.substring(1);
85	        for (String code : NATIONAL_LENGTH.keySet()) {
86	            if (digits.startsWith(code)) {
87	                return "+" + code + " " + groupInThrees(digits.substring(code.length()));
88	            }
89	        }
90	        return e164;
91	    }
92	
93	    /** Groups a run of digits into space-separated groups of three, from the left. */
94	    private static String groupInThrees(String national) {
95	        StringBuilder grouped = new StringBuilder();
96	        for (int i = 0; i < national.length(); i++) {
97	            if (i > 0 && i % 3 == 0) {
98	                grouped.append(' ');
99	            }
100	            grouped.append(national.charAt(i));
101	        }
102	        return grouped.toString();
103	    }
104	}
